def season_from_month(month_index):
    month = (month_index - 1) % 12 + 1
    if month in (12, 1, 2):
        return 'Winter'
    if month in (3, 4, 5):
        return 'Spring'
    if month in (6, 7, 8):
        return 'Summer'
    return 'Fall'

def fiscal_quarter(month, fiscal_start_month):
    offset = (month - fiscal_start_month) % 12
    return offset // 3 + 1

def clock_angle_diff(hour, minute):
    hour_angle = (hour % 12) * 30 + minute * 0.5
    minute_angle = minute * 6
    diff = abs(hour_angle - minute_angle)
    return min(diff, 360 - diff)

def time_from_am_pm_string(time_str):
    time_part, period = time_str.split(' ')
    h, m = time_part.split(':')
    h = int(h) % 12
    if period == 'PM':
        h += 12
    return h*60 + int(m)

def business_days_between(date1, date2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def doy(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m-1]) + d
    def ordinal(date):
        y, m, d = date
        return 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 + doy(y, m, d)
    o1 = ordinal(date1)
    o2 = ordinal(date2)
    count = 0
    for o in range(o1, o2):
        if (o + 5) % 7 not in (5, 6):
            count += 1
    return count

def combine_date_time_to_minutes(year, month, day, time_str):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    doy = sum(lengths[:month-1]) + day
    h, m = time_str.split(':')
    return (doy-1)*1440 + int(h)*60 + int(m)

def time_zone_shift(time_str, hour_offset):
    h, m = time_str.split(':')
    total = int(h)*60 + int(m) + hour_offset*60
    day_offset = total // 1440
    rem = total % 1440
    return (day_offset, f'{rem//60:02d}:{rem%60:02d}')

def is_same_week_simplified(date1, date2):
    def week_num(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if y % 4 == 0 and (y % 100 != 0 or y % 400 == 0):
            lengths[1] = 29
        doy = sum(lengths[:m-1]) + d
        return (doy - 1)//7 + 1
    y1, m1, d1 = date1
    y2, m2, d2 = date2
    return week_num(y1, m1, d1) == week_num(y2, m2, d2)

def quarter_end_date(year, quarter):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    end_month = quarter*3
    return (year, end_month, lengths[end_month-1])

def total_seconds_between(t1, t2):
    def to_sec(t):
        h, m, s = t.split(':')
        return int(h)*3600 + int(m)*60 + int(s)
    a, b = to_sec(t1), to_sec(t2)
    diff = b - a
    if diff < 0:
        diff += 86400
    return diff

def average_time(times):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    total = sum(to_min(t) for t in times)
    avg = total // len(times)
    return f'{avg//60:02d}:{avg%60:02d}'

def midpoint_date(date1, date2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def doy(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m-1]) + d
    def ordinal(date):
        y, m, d = date
        return 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 + doy(y, m, d)
    def from_ordinal(o):
        y = 1
        while ordinal((y+1,1,1)) <= o:
            y *= 2
        lo, hi = 1, y+1
        while lo < hi:
            mid = (lo+hi)//2
            if ordinal((mid+1,1,1)) <= o:
                lo = mid+1
            else:
                hi = mid
        year = lo
        remaining = o - ordinal((year,1,1)) + 1
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(year):
            lengths[1] = 29
        month = 1
        while remaining > lengths[month-1]:
            remaining -= lengths[month-1]
            month += 1
        return (year, month, remaining)
    o1 = ordinal(date1)
    o2 = ordinal(date2)
    mid = o1 + (o2 - o1)//2
    return from_ordinal(mid)
